import enemyFile from "./enemies.json";
import type { Enemy } from "./types";

const ENEMIES = enemyFile.enemies as Enemy[];

function enemiesOfFaction(faction: string): Enemy[] {
  return ENEMIES.filter((enemy) => enemy.faction === faction);
}

/** Wiki tab: faction → enemy roster, generated by `npm run sync:enemies`. */
export const WIKI_FACTIONS = [
  {
    id: "terminids" as const,
    label: "Terminids",
    enemies: enemiesOfFaction("Terminids"),
  },
  {
    id: "automatons" as const,
    label: "Automatons",
    enemies: enemiesOfFaction("Automatons"),
  },
  {
    id: "illuminate" as const,
    label: "Illuminate",
    enemies: enemiesOfFaction("Illuminate"),
  },
  {
    id: "super-earth" as const,
    label: "Super Earth",
    enemies: enemiesOfFaction("Super Earth"),
  },
] as const;

export type WikiFactionId = (typeof WIKI_FACTIONS)[number]["id"];

/** The day the enemy data was last read from the wiki, as YYYY-MM-DD. */
export const ENEMY_SNAPSHOT_DATE = enemyFile.fetchedAt.slice(0, 10);

export function enemiesForWikiFaction(id: WikiFactionId): Enemy[] {
  const row = WIKI_FACTIONS.find((f) => f.id === id);
  return row?.enemies ?? [];
}
